'use client';

import { useEffect, useRef, useState } from 'react';

import type { LeafState } from '@/lib/attack-tree';
import type { FacePage, TwoFaces } from '@/lib/two-faces';
import data from '@/lib/two-faces.data.json';

import { JanusMark } from '../ui/janus-mark';
import { LaunchSection } from './launch-section';
import { useReducedMotion } from './use-reduced-motion';

// Generated by buildTwoFaces from the recorded runs; two-faces.test.ts keeps it equal to them.
const FACES = data as unknown as TwoFaces;

const NAMES: Record<string, string> = {
  'carmen-retired': 'Carmen',
  'competent-baseline': 'Baseline',
  'diego-commuter': 'Diego',
  'rosa-meticulous': 'Rosa',
  'tomas-hurried': 'Tomás',
};

const DETECTORS: Record<string, string> = {
  performance: 'Slow page',
  backtrack: 'Went back',
  abandonment: 'Gave up',
  'rage-click': 'Rage click',
  'extra-steps': 'Extra steps',
};

const STATE_TEXT: Record<LeafState, string> = {
  exploited: 'exploitable',
  fixed: 'fixed · verified',
  refused: 'tried · held',
  blocked: 'blocked by scope',
};

const SOURCES = [
  'apps/web-console/public/demo/runs/01M79YYRATK9KNKWMMD4317E77.json',
  'apps/web-console/public/demo/runs/01M79ZA35SZ9QRNF6K3AAGXNQN.json',
  'apps/web-console/public/demo/runs/01M79ZC3PHE7YQA5EQR02YHTBC.json',
];

const maxFriction = Math.max(1, ...FACES.pages.flatMap((p) => Object.values(p.friction)));

function UxCard({ page, i }: { page: FacePage; i: number }) {
  const friction = Object.entries(page.friction).sort((a, b) => b[1] - a[1]);
  return (
    <article className="face-card" data-face="ux">
      <header>
        <span className="face-card__n">{String(i + 1).padStart(2, '0')}</span>
        <h4>{page.label}</h4>
        <code>/#{page.route}</code>
      </header>
      <p className="face-card__line">
        <b>{page.reached}</b>/{FACES.sessions} sessions · {page.steps} steps
      </p>
      <ul className="face-card__people" aria-label="Who got here">
        {page.personas.map((p) => (
          <li key={p} title={NAMES[p] ?? p}>
            {(NAMES[p] ?? p)[0]}
          </li>
        ))}
      </ul>
      <ul className="face-card__bars">
        {friction.length === 0 && <li className="face-card__calm">No friction signals</li>}
        {friction.map(([d, n]) => (
          <li key={d}>
            <span>{DETECTORS[d] ?? d}</span>
            <i style={{ width: `${(n / maxFriction) * 100}%` }} />
            <b>{n}</b>
          </li>
        ))}
      </ul>
    </article>
  );
}

function SecurityCard({ page, i }: { page: FacePage; i: number }) {
  return (
    <article className="face-card" data-face="security">
      <header>
        <span className="face-card__n">{String(i + 1).padStart(2, '0')}</span>
        <h4>{page.label}</h4>
        <code>/#{page.route}</code>
      </header>
      {page.pageState ? (
        <p className="face-card__alert" data-state={page.pageState}>
          The page itself:{' '}
          {page.pageState === 'exploited' ? 'XSS, exploitable' : STATE_TEXT[page.pageState]}
        </p>
      ) : (
        <p className="face-card__line">{page.endpoints.length} API calls behind it</p>
      )}
      <ul className="face-card__eps">
        {page.endpoints.length === 0 && <li className="face-card__calm">No API calls recorded</li>}
        {page.endpoints.map((e) => (
          <li key={e.endpoint} data-state={e.state ?? 'none'}>
            <i aria-hidden />
            <code>{e.endpoint}</code>
            <span>{e.state ? STATE_TEXT[e.state] : 'not attacked'}</span>
          </li>
        ))}
      </ul>
    </article>
  );
}

export function TwoFacesSection() {
  const figure = useRef<HTMLDivElement>(null);
  const target = useRef(50);
  const current = useRef(50);
  const touched = useRef(false);
  const [mobileFace, setMobileFace] = useState<'ux' | 'security'>('ux');
  const reduced = useReducedMotion();

  useEffect(() => {
    const el = figure.current;
    if (!el) return;
    let raf = 0;
    let visible = false;
    const start = performance.now();
    const set = (v: number) => el.style.setProperty('--seam', `${v.toFixed(2)}%`);
    const tick = (now: number) => {
      if (!touched.current && !reduced) {
        // Until the visitor takes over, the seam breathes between the two faces.
        target.current = 50 + Math.sin((now - start) / 1600) * 22;
      }
      current.current += (target.current - current.current) * 0.12;
      set(current.current);
      if (visible) raf = requestAnimationFrame(tick);
    };
    const io = new IntersectionObserver(([e]) => {
      visible = e?.isIntersecting ?? false;
      cancelAnimationFrame(raf);
      if (visible) raf = requestAnimationFrame(tick);
    });
    io.observe(el);
    const onMove = (e: PointerEvent) => {
      const r = el.getBoundingClientRect();
      touched.current = true;
      target.current = Math.min(96, Math.max(4, ((e.clientX - r.left) / r.width) * 100));
    };
    el.addEventListener('pointermove', onMove);
    set(50);
    return () => {
      io.disconnect();
      cancelAnimationFrame(raf);
      el.removeEventListener('pointermove', onMove);
    };
  }, [reduced]);

  const nudge = (delta: number) => {
    touched.current = true;
    target.current = Math.min(96, Math.max(4, target.current + delta));
  };

  const exploitedPages = FACES.pages.filter(
    (p) => p.pageState === 'exploited' || p.endpoints.some((e) => e.state === 'exploited'),
  ).length;

  return (
    <LaunchSection
      id="two-faces"
      title={
        <>
          One shop, <em>two faces</em>
        </>
      }
      lede="The same nine pages of Juice Shop, as the shoppers lived them and as the attacker found them. The bridge is real: the API calls each shopper's browser made from each page. Move the seam, or switch faces on a phone, to compare them page by page."
      sources={SOURCES}
    >
      <div className="faces-head">
        <div data-face="ux">
          <p className="eyebrow">What the shoppers felt · SynthLab</p>
          <p className="faces-head__big">
            <b>{FACES.passed}</b> of {FACES.sessions} sessions bought the juice
          </p>
        </div>
        <div data-face="security">
          <p className="eyebrow">What the attacker found · Red Team</p>
          <p className="faces-head__big">
            <b>{exploitedPages}</b> of {FACES.pages.length} pages touch something exploitable
          </p>
        </div>
      </div>

      <div className="faces-switch" role="group" aria-label="Face">
        <button
          type="button"
          aria-pressed={mobileFace === 'ux'}
          onClick={() => setMobileFace('ux')}
        >
          Shoppers
        </button>
        <button
          type="button"
          aria-pressed={mobileFace === 'security'}
          onClick={() => setMobileFace('security')}
        >
          Attacker
        </button>
      </div>

      <div className="faces" ref={figure} data-mobile-face={mobileFace}>
        <div className="faces__layer" data-face="ux">
          {FACES.pages.map((p, i) => (
            <UxCard key={p.route} page={p} i={i} />
          ))}
        </div>
        <div className="faces__layer" data-face="security" aria-hidden={false}>
          {FACES.pages.map((p, i) => (
            <SecurityCard key={p.route} page={p} i={i} />
          ))}
        </div>
        <div
          className="faces__seam"
          role="slider"
          tabIndex={0}
          aria-label="Move between the shoppers' face and the attacker's face"
          aria-valuemin={0}
          aria-valuemax={100}
          aria-valuenow={50}
          onKeyDown={(e) => {
            if (e.key === 'ArrowLeft') nudge(-5);
            if (e.key === 'ArrowRight') nudge(5);
          }}
        >
          <span className="faces__knob">
            <JanusMark size={46} />
          </span>
          <span className="faces__tag" data-face="ux">
            ← Shoppers
          </span>
          <span className="faces__tag" data-face="security">
            Attacker →
          </span>
        </div>
      </div>
    </LaunchSection>
  );
}
